-- 0046  Upbrains invoice extraction, corrected from the group's own call.
--
-- Migration 0045 recorded this operation from the flow's configuration and its
-- saved test run, before the group had called it. On 12 October 2026 the group
-- sent a one-page invoice PDF to the flow's webhook and received the result
-- (status 200, about 15 seconds). Two things in the record were not right:
--
--   * The address. The call that waits for the flow's Return Response step and
--     returns the extraction is the webhook address followed by /sync. The
--     record had the address without it.
--   * The response. The saved run's display was cut short, so the record
--     missed what the real response carries: the header fields PaymentTerm,
--     VendorTaxId and BillingAddressRecipient; Unit and TaxRate on each line;
--     and file_name, document_type, content, csv_content and needs_review
--     around them.
--
-- The OpenAPI document was corrected
-- (frontend/public/specs/upbrains-invoice-extract-openapi.json,
-- sha256 95dec0e2ff725467ebb5b2ac5be26f49f4672a302efead8222ba8e530f50836c),
-- and the schema rows were rebuilt from it with the importer's own code, as in
-- 0045. This migration replaces the operation's schemas, fields and parameter
-- with the rebuilt ones and corrects the address and the description. The
-- name, category, company and review status set in 0045 are not touched; the
-- {flowId} placeholder stays, because the flow's address is its only secret.

-- ----------------------------------------------------------------- preconditions

do $$
declare found integer;
begin
  select count(*) into found from public.apis
   where id = '974405cd-82b2-4e76-a628-278a56ac4e9a'
     and api_endpoint = 'https://agents.upbrains.ai/v1/webhooks/{flowId}';
  if found <> 1 then
    raise exception '0046 precondition failed: the Upbrains record of 0045 is missing or its address was already changed.';
  end if;
end
$$;

-- ---------------------------------------------------------------------- changes

update public.apis
   set api_endpoint = 'https://agents.upbrains.ai/v1/webhooks/{flowId}/sync',
       description = $desc0046$Starts the flow with a PDF carried as base64 inside a JSON body, waits for the flow's Return Response step and returns the extraction result of the Standard Invoice Extractor. The /sync suffix is what makes the call wait for the result. The flow's page also shows the address without the suffix and a /test form that runs the flow's draft; the group has called only the /sync form.$desc0046$
 where id = '974405cd-82b2-4e76-a628-278a56ac4e9a';

-- Fields go with their schema (on delete cascade).
delete from public.api_schema where api_id = '974405cd-82b2-4e76-a628-278a56ac4e9a';
delete from public.api_parameter where api_id = '974405cd-82b2-4e76-a628-278a56ac4e9a';

